export class BookController {
  constructor(private service: BookService) {}

  create = async (req: Request, res: Response, next: NextFunction) => {
    try {
      // Extract trusted userId from Request Context (never client body)
      const trustedUserId = req.context.userId;
      const newBook = await this.service.createBook(req.body, trustedUserId);
      return res.status(201).json({ status: 201, data: newBook });
    } catch (err) {
      next(err); // Forward to Global Error Middleware
    }
  };
}

// ─── 2. SERVICE LAYER (100% HTTP Agnostic) ───
export class BookService {
  constructor(private repo: BookRepository) {}

  async createBook(payload: { title: string; author: string }, userId: string) {
    if (!payload.title) throw new Error('VALIDATION_ERROR: Title is required');
    return await this.repo.insert({ ...payload, userId });
  }
}

// ─── 3. REPOSITORY LAYER (Single Responsibility) ───
export class BookRepository {
  async insert(record: { title: string; author: string; userId: string }) {
    return await db.query('INSERT INTO books (title, author, user_id) VALUES ($1, $2, $3) RETURNING *', [
      record.title,
      record.author,
      record.userId
    ]);
  }
}

package main

import (
    "context"
    "encoding/json"
    "net/http"
)

// 1. Controller Layer
type BookHandler struct {
    service *BookService
}

func (h *BookHandler) CreateBook(w http.ResponseWriter, r *http.Request) {
    // Read trusted claims from context (populated by Auth Middleware)
    userId, ok := r.Context().Value("userId").(string)
    if !ok {
        http.Error(w, "401 Unauthorized", http.StatusUnauthorized)
        return
    }

    var req CreateBookRequest
    if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
        http.Error(w, "400 Bad Request: Invalid JSON", http.StatusBadRequest)
        return
    }

    book, err := h.service.CreateBook(r.Context(), req, userId)
    if err != nil {
        http.Error(w, err.Error(), http.StatusInternalServerError)
        return
    }

    w.WriteHeader(http.StatusCreated)
    json.NewEncoder(w).Encode(book)
}

// 2. Service Layer (HTTP Agnostic)
type BookService struct {
    repo *BookRepository
}

func (s *BookService) CreateBook(ctx context.Context, req CreateBookRequest, userId string) (*Book, error) {
    return s.repo.Insert(ctx, req.Title, req.Author, userId)
}

